/**
 * Common JavaScript for Enterprise Voice AI
 * Handles CSRF, Centrifugo Realtime, Global Header Balance, Language Toggle, and Sidebar.
 */

// Universal Embed Token & Client ID Fetch Interceptor
(function() {
  try {
    const urlParams = new URLSearchParams(window.location.search);
    const embedToken = urlParams.get('token') || urlParams.get('key') || window.EMBED_TOKEN || '';
    const embedClientId = urlParams.get('client_id') || window.EMBED_CLIENT_ID || '';
    const embedLocale = urlParams.get('locale') || urlParams.get('lang') || window.EMBED_LOCALE || '';

    if (embedToken) window.EMBED_TOKEN = embedToken;
    if (embedClientId) window.EMBED_CLIENT_ID = embedClientId;
    if (embedLocale) window.EMBED_LOCALE = embedLocale;

    const originalFetch = window.fetch;
    window.fetch = function(resource, init) {
      init = init || {};
      let url = (typeof resource === 'string') ? resource : (resource && resource.url ? resource.url : '');
      const isRequestObj = (typeof resource === 'object' && resource !== null && !(resource instanceof URL) && typeof resource.url === 'string');

      const curToken = window.EMBED_TOKEN || '';
      const curClientId = window.EMBED_CLIENT_ID || '';
      const curLocale = window.EMBED_LOCALE || '';

      if (curToken && url && (url.startsWith('/api/') || (url.startsWith('http') && url.includes('/api/')))) {
        try {
          const parsed = new URL(url, window.location.origin);
          if (curToken && !parsed.searchParams.has('token') && !parsed.searchParams.has('key')) {
            parsed.searchParams.set('token', curToken);
          }
          if (curClientId && !parsed.searchParams.has('client_id')) {
            parsed.searchParams.set('client_id', curClientId);
          }
          if (curLocale && !parsed.searchParams.has('locale') && !parsed.searchParams.has('lang')) {
            parsed.searchParams.set('locale', curLocale);
          }
          url = parsed.pathname + parsed.search + parsed.hash;
        } catch (_) {}

        if (!init.headers) init.headers = {};
        if (init.headers instanceof Headers) {
          if (curToken && !init.headers.has('Authorization')) init.headers.set('Authorization', 'Bearer ' + curToken);
          if (curClientId && !init.headers.has('X-Client-ID')) init.headers.set('X-Client-ID', curClientId);
        } else if (Array.isArray(init.headers)) {
          if (curToken) init.headers.push(['Authorization', 'Bearer ' + curToken]);
          if (curClientId) init.headers.push(['X-Client-ID', curClientId]);
        } else if (typeof init.headers === 'object') {
          if (curToken && !init.headers['Authorization']) init.headers['Authorization'] = 'Bearer ' + curToken;
          if (curClientId && !init.headers['X-Client-ID']) init.headers['X-Client-ID'] = curClientId;
        }
      }

      if (isRequestObj && url) {
        return originalFetch.call(this, url, init);
      }
      return originalFetch.call(this, url || resource, init);
    };
  } catch (e) {
    console.debug('Fetch interceptor init note:', e);
  }
})();

// CSRF Token Helper
function getCookie(name) {
  let cookieValue = null;
  if (document.cookie && document.cookie !== '') {
    const cookies = document.cookie.split(';');
    for (let i = 0; i < cookies.length; i++) {
      const cookie = cookies[i].trim();
      if (cookie.substring(0, name.length + 1) === (name + '=')) {
        cookieValue = decodeURIComponent(cookie.substring(name.length + 1));
        break;
      }
    }
  }
  return cookieValue;
}

function escapeHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

// Sidebar Collapse / Expand Toggle
function toggleSidebar() {
  const sidebar = document.getElementById('sidebar');
  const icon = document.getElementById('sidebar-toggle-icon');
  if (!sidebar) return;

  const isExpanded = sidebar.classList.contains('sidebar-expanded');
  if (isExpanded) {
    sidebar.classList.remove('sidebar-expanded');
    sidebar.classList.add('sidebar-collapsed');
    if (icon) icon.classList.add('rotate-180');
    localStorage.setItem('sidebar_collapsed', 'true');
  } else {
    sidebar.classList.remove('sidebar-collapsed');
    sidebar.classList.add('sidebar-expanded');
    if (icon) icon.classList.remove('rotate-180');
    localStorage.setItem('sidebar_collapsed', 'false');
  }
}

// Initialize Sidebar state from localStorage
function initSidebarState() {
  if (localStorage.getItem('sidebar_collapsed') === 'true') {
    const sidebar = document.getElementById('sidebar');
    const icon = document.getElementById('sidebar-toggle-icon');
    if (sidebar) {
      sidebar.classList.remove('sidebar-expanded');
      sidebar.classList.add('sidebar-collapsed');
    }
    if (icon) icon.classList.add('rotate-180');
  }
}

// Global Wallet Balance in Header
async function loadHeaderBalance() {
  const hVal = document.getElementById('header-balance-val');
  if (!hVal) return;
  try {
    const res = await fetch('/api/billing/wallet/');
    const data = await res.json();
    if (data.status === 'success') {
      const w = data.wallet;
      const hCurr = document.getElementById('header-balance-curr');
      hVal.innerText = w.balance.toFixed(2);
      if (hCurr) hCurr.innerText = w.currency;
    }
  } catch (err) {
    console.debug('Header balance fetch error:', err);
  }
}

// Centrifugo Real-Time Connection
let globalCentrifugeClient = null;
window.globalCentrifugeClient = null;
let currentCentrifugoState = 'connected';

async function initGlobalCentrifugo() {
  const statusEl = document.getElementById('centrifugo-status');
  try {
    const res = await fetch('/api/token/');
    const data = await res.json();
    if (data.status === 'success' && data.centrifugo_token && typeof Centrifuge !== 'undefined') {
      globalCentrifugeClient = new Centrifuge(data.centrifugo_ws_url, {
        token: data.centrifugo_token
      });
      window.globalCentrifugeClient = globalCentrifugeClient;

      globalCentrifugeClient.on('connecting', function() {
        currentCentrifugoState = 'connecting';
        updateCentrifugoStatusBadge();
      });

      globalCentrifugeClient.on('connected', function() {
        currentCentrifugoState = 'connected';
        updateCentrifugoStatusBadge();
      });

      globalCentrifugeClient.on('disconnected', function() {
        currentCentrifugoState = 'disconnected';
        updateCentrifugoStatusBadge();
      });

      globalCentrifugeClient.connect();
    }
  } catch (e) {
    console.debug('Centrifugo init error:', e);
  }
}

function updateCentrifugoStatusBadge() {
  const statusEl = document.getElementById('centrifugo-status');
  if (!statusEl) return;
  const lang = getCurrentLanguage();
  if (currentCentrifugoState === 'connecting') {
    statusEl.className = 'inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-slate-50 border border-slate-200 text-slate-600 font-medium text-xs shadow-2xs';
    statusEl.innerHTML = `<span class="w-2 h-2 rounded-full bg-amber-400"></span> ${window.t('centrifugo_connecting', 'التزامن السحابي: جاري الاتصال...')}`;
  } else if (currentCentrifugoState === 'connected') {
    statusEl.className = 'inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-slate-50 border border-slate-200 text-slate-600 font-medium text-xs shadow-2xs';
    statusEl.innerHTML = `<span class="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span> ${window.t('centrifugo_connected', 'التزامن السحابي: متصل')}`;
  } else {
    statusEl.className = 'inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-slate-50 border border-slate-200 text-slate-600 font-medium text-xs shadow-2xs';
    statusEl.innerHTML = `<span class="w-2 h-2 rounded-full bg-rose-500"></span> ${window.t('centrifugo_disconnected', 'التزامن السحابي: غير متصل')}`;
  }
}

// Toast Notifications Helper
function showToast(message, type = 'info') {
  let toastContainer = document.getElementById('toast-container');
  if (!toastContainer) {
    toastContainer = document.createElement('div');
    toastContainer.id = 'toast-container';
    toastContainer.className = 'fixed bottom-5 end-5 z-50 flex flex-col gap-2 pointer-events-none max-w-sm';
    document.body.appendChild(toastContainer);
  }

  const toast = document.createElement('div');
  const bgClass = type === 'success' 
    ? 'bg-slate-900 text-white border border-emerald-500/30' 
    : type === 'error' 
    ? 'bg-slate-900 text-white border border-rose-500/30' 
    : 'bg-slate-900 text-white border border-slate-700';

  toast.className = `p-3 rounded-lg shadow-lg text-xs font-medium flex items-center gap-2 pointer-events-auto transition-all duration-300 transform translate-y-4 opacity-0 ${bgClass}`;
  const iconSvg = type === 'success'
    ? '<svg class="w-4 h-4 text-emerald-400 shrink-0" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>'
    : type === 'error'
    ? '<svg class="w-4 h-4 text-rose-400 shrink-0" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>'
    : '<svg class="w-4 h-4 text-violet-400 shrink-0" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>';
  toast.innerHTML = `${iconSvg} <span>${escapeHtml(message)}</span>`;

  toastContainer.appendChild(toast);
  requestAnimationFrame(() => {
    toast.classList.remove('translate-y-4', 'opacity-0');
  });

  setTimeout(() => {
    toast.classList.add('translate-y-4', 'opacity-0');
    setTimeout(() => toast.remove(), 350);
  }, 4000);
}

