// Aliases for compatibility
const COMMON_I18N = APP_I18N;
window.APP_I18N = APP_I18N;
window.COMMON_I18N = APP_I18N;

// 6 Supported Platform Languages Configuration
const SUPPORTED_LANGUAGES = [
  { code: 'ar', label: 'العربية', flag: '🇸🇦', dir: 'rtl', short: 'عربي' },
  { code: 'en', label: 'English', flag: '🇬🇧', dir: 'ltr', short: 'EN' },
  { code: 'tr', label: 'Türkçe', flag: '🇹🇷', dir: 'ltr', short: 'TR' },
  { code: 'fr', label: 'Français', flag: '🇫🇷', dir: 'ltr', short: 'FR' },
  { code: 'de', label: 'Deutsch', flag: '🇩🇪', dir: 'ltr', short: 'DE' },
  { code: 'es', label: 'Español', flag: '🇪🇸', dir: 'ltr', short: 'ES' }
];
const VALID_LANGS = ['ar', 'en', 'tr', 'fr', 'de', 'es'];
window.SUPPORTED_LANGUAGES = SUPPORTED_LANGUAGES;
window.VALID_LANGS = VALID_LANGS;

// Current Language Resolution
let currentLang = localStorage.getItem('app_lang') || localStorage.getItem('voice_app_lang') || 'ar';
if (!VALID_LANGS.includes(currentLang)) {
  currentLang = 'ar';
}

function getCurrentLanguage() {
  return currentLang;
}
window.getCurrentLanguage = getCurrentLanguage;

function getI18nText(key, lang) {
  const l = lang || currentLang || 'ar';
  if (APP_I18N[l] && APP_I18N[l][key] !== undefined) {
    return APP_I18N[l][key];
  }
  if (APP_I18N['ar'] && APP_I18N['ar'][key] !== undefined) {
    return APP_I18N['ar'][key];
  }
  if (APP_I18N['en'] && APP_I18N['en'][key] !== undefined) {
    return APP_I18N['en'][key];
  }
  return null;
}
window.getI18nText = getI18nText;

window.t = function(key, fallback) {
  const val = getI18nText(key, currentLang);
  return (val !== null && val !== undefined) ? val : (fallback !== undefined ? fallback : key);
};

